ALTER TABLE movements ADD COLUMN lot_id INTEGER REFERENCES lots(id);
ALTER TABLE movements ADD COLUMN operation_id INTEGER REFERENCES operations(id);
ALTER TABLE servings ADD COLUMN operation_id INTEGER REFERENCES operations(id);
ALTER TABLE servings ADD COLUMN card_id INTEGER REFERENCES technical_cards(id);
ALTER TABLE servings ADD COLUMN menu_id INTEGER REFERENCES menus(id);
ALTER TABLE recipes ADD COLUMN approved_card INTEGER REFERENCES technical_cards(id);
CREATE TABLE users(id INTEGER PRIMARY KEY, name TEXT NOT NULL, login TEXT NOT NULL UNIQUE COLLATE NOCASE,
 password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('Administrador','Estoque','Nutricionista','Consulta')), crn TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE audit(id INTEGER PRIMARY KEY, stamp TEXT NOT NULL, actor INTEGER REFERENCES users(id), action TEXT NOT NULL, entity TEXT NOT NULL, detail TEXT NOT NULL, previous TEXT NOT NULL, hash TEXT NOT NULL);
CREATE TABLE periods(month TEXT PRIMARY KEY, closed INTEGER NOT NULL, reason TEXT NOT NULL, actor INTEGER NOT NULL REFERENCES users(id), stamp TEXT NOT NULL);
CREATE TABLE suppliers(id INTEGER PRIMARY KEY, name TEXT NOT NULL, document TEXT NOT NULL UNIQUE, family INTEGER NOT NULL CHECK(family IN (0,1)), caf TEXT NOT NULL);
CREATE TABLE operations(id INTEGER PRIMARY KEY, kind TEXT NOT NULL, date TEXT NOT NULL, actor INTEGER NOT NULL REFERENCES users(id), reason TEXT NOT NULL, reversal_of INTEGER UNIQUE REFERENCES operations(id));
CREATE TABLE receipts(id INTEGER PRIMARY KEY, supplier INTEGER NOT NULL REFERENCES suppliers(id), item INTEGER NOT NULL REFERENCES items(id), invoice TEXT NOT NULL, process TEXT NOT NULL, contract TEXT NOT NULL, method TEXT NOT NULL, funding TEXT NOT NULL CHECK(funding IN ('FNDE','Próprios')), category TEXT NOT NULL, grams INTEGER NOT NULL CHECK(grams>0), cents INTEGER NOT NULL CHECK(cents>0), operation_id INTEGER NOT NULL UNIQUE REFERENCES operations(id));
CREATE TABLE lots(id INTEGER PRIMARY KEY, item INTEGER NOT NULL REFERENCES items(id), receipt INTEGER REFERENCES receipts(id), batch TEXT NOT NULL, expiry TEXT, location TEXT NOT NULL, legacy INTEGER NOT NULL DEFAULT 0, parent INTEGER REFERENCES lots(id));
CREATE TABLE payments(id INTEGER PRIMARY KEY, receipt INTEGER NOT NULL REFERENCES receipts(id), cents INTEGER NOT NULL CHECK(cents>0), document TEXT NOT NULL, operation_id INTEGER NOT NULL UNIQUE REFERENCES operations(id));
CREATE TABLE resources(id INTEGER PRIMARY KEY, cents INTEGER NOT NULL CHECK(cents>0), document TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('Repasse FNDE','Saldo reprogramado')), operation_id INTEGER NOT NULL UNIQUE REFERENCES operations(id));
CREATE TABLE technical_cards(id INTEGER PRIMARY KEY, recipe INTEGER NOT NULL REFERENCES recipes(id), revision INTEGER NOT NULL, snapshot TEXT NOT NULL, hash TEXT NOT NULL, actor INTEGER NOT NULL REFERENCES users(id), stamp TEXT NOT NULL, UNIQUE(recipe,revision));
CREATE TABLE menus(id INTEGER PRIMARY KEY, school INTEGER NOT NULL REFERENCES schools(id), date TEXT NOT NULL, meal TEXT NOT NULL, age_group TEXT NOT NULL, diet TEXT NOT NULL, card INTEGER NOT NULL REFERENCES technical_cards(id), planned INTEGER NOT NULL CHECK(planned>0), snapshot TEXT NOT NULL, actor INTEGER NOT NULL REFERENCES users(id), stamp TEXT NOT NULL, supersedes INTEGER UNIQUE REFERENCES menus(id));
CREATE TABLE documents(id INTEGER PRIMARY KEY, entity TEXT NOT NULL, entity_id INTEGER NOT NULL, name TEXT NOT NULL, stored_name TEXT NOT NULL, hash TEXT NOT NULL, actor INTEGER NOT NULL REFERENCES users(id), stamp TEXT NOT NULL);
CREATE TABLE food_assessments(id INTEGER PRIMARY KEY,item INTEGER NOT NULL REFERENCES items(id),category TEXT NOT NULL,allowed INTEGER NOT NULL,reason TEXT NOT NULL,actor INTEGER NOT NULL REFERENCES users(id),stamp TEXT NOT NULL);
CREATE TABLE lot_evidence(lot INTEGER PRIMARY KEY REFERENCES lots(id),supplier INTEGER NOT NULL REFERENCES suppliers(id),invoice TEXT NOT NULL,reason TEXT NOT NULL,actor INTEGER NOT NULL REFERENCES users(id),stamp TEXT NOT NULL);
INSERT INTO lots(item,batch,location,legacy) SELECT id,'LEGADO — conferir documentação e validade','central',1 FROM items;
UPDATE movements SET lot_id=(SELECT id FROM lots WHERE lots.item=movements.item AND legacy=1);
CREATE INDEX lot_history ON movements(lot_id,date);
CREATE INDEX operation_dates ON operations(date);
CREATE TRIGGER immutable_movements_update BEFORE UPDATE ON movements BEGIN SELECT RAISE(ABORT,'Movimentos são imutáveis. Use estorno.'); END;
CREATE TRIGGER immutable_movements_delete BEFORE DELETE ON movements BEGIN SELECT RAISE(ABORT,'Movimentos são imutáveis. Use estorno.'); END;
CREATE TRIGGER require_operation BEFORE INSERT ON movements WHEN NEW.operation_id IS NULL OR NEW.lot_id IS NULL BEGIN SELECT RAISE(ABORT,'Movimento exige operação e lote.'); END;
PRAGMA user_version=2;
